draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // optimism face
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 30, 0, 2 * Math.PI);
  ctx.fill();

  // smile
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 90, 20, 0, Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 - 50 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 + 50 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();

  // good things text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Good Things', W/2, H/2 + 100 + 20 * Math.sin(t));

  ctx.restore();
}
